"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["67263"],{98295(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.tipo_de_ato_sem_versao_vigente","status":422,"titulo":"N\xe3o h\xe1 vers\xe3o vigente do tipo de ato na data da publica\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.tipo_de_ato_sem_versao_vigente","requisitos":["UNI-REQ-0019","UNI-REQ-0163","UNI-REQ-0406"],"oQueAconteceu":["Publicar ou retificar um processo seletivo registra um ato normativo em\\nPublica\xe7\xf5es, na mesma opera\xe7\xe3o que grava a vers\xe3o da configura\xe7\xe3o e a\\ndivulga\xe7\xe3o do certame. Nessa opera\xe7\xe3o, o tipo de ato declarado \xe9 conferido\\nno cat\xe1logo: ele precisa ter vers\xe3o vigente **no dia da divulga\xe7\xe3o**.","O dia que vale \xe9 o dia civil do instante em que o sistema divulga o ato,\\nno fuso institucional (UNI-REQ-0111). A data que o documento declara, a\\nimpressa nele, **n\xe3o escolhe** a vers\xe3o do tipo (UNI-REQ-0406): um\\ndocumento datado de uma semana atr\xe1s n\xe3o busca a vers\xe3o que vigorava\\nent\xe3o.","A recusa \xe9 **s\xedncrona**: chega na pr\xf3pria resposta da publica\xe7\xe3o, antes de\\nqualquer grava\xe7\xe3o. **Nada fica gravado**: nenhuma vers\xe3o, nenhum ato,\\nnenhuma divulga\xe7\xe3o. O rascunho \xe9 preservado, e a opera\xe7\xe3o pode ser\\nrepetida assim que o tipo tiver vers\xe3o vigente.","A recusa vale tamb\xe9m para os **tipos de ato que o cronograma declara**. Ao\\npublicar, e ao retificar com um tipo declarado pela primeira vez, a\\nclassifica\xe7\xe3o de cada tipo (se congela a configura\xe7\xe3o, se \xe9 \xfanico, se \xe9\\nresultado) \xe9 lida do cat\xe1logo na data de hoje e congelada na vers\xe3o\\npublicada. Tipo declarado sem vers\xe3o vigente hoje n\xe3o tem classifica\xe7\xe3o a\\ncongelar. O tipo que a vers\xe3o vigente j\xe1 congelou n\xe3o \xe9 relido na\\nretifica\xe7\xe3o (UNI-REQ-0163)."],"comoResolver":["Confirme, no cat\xe1logo de tipos de ato de Publica\xe7\xf5es, que o c\xf3digo tem uma\\nvers\xe3o vigente no dia da divulga\xe7\xe3o, que \xe9 hoje: tipos de ato t\xeam vig\xeancia\\npr\xf3pria. Cadastre uma vers\xe3o vigente ou escolha outro tipo de ato. Para o\\ntipo declarado no cronograma pela primeira vez vale a mesma regra: vigente\\nhoje, ou declare outro tipo no cronograma.","Se o tipo de ato n\xe3o existe no cat\xe1logo, \xe9 preciso cadastr\xe1-lo antes; ver\\n[`tipo_ato.nao_encontrado`](/erros/uniplus.publicacoes.tipo_ato.nao_encontrado)\\npara o comportamento equivalente no cadastro direto de Publica\xe7\xf5es."],"ondeAparece":["Publica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o do processo seletivo","Fechamento de retifica\xe7\xe3o","Publica\xe7\xe3o de documento avulso e de item do edital"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);